entries[37826] = { ["name"] = "Saat der Verderbnis", ["text"] = "Unbegrenzte Reichweite\nSofort\nPflanzt dem gegnerischen Ziel eine dämonische Saat ein, die nach Ablauf von 12 Sek. explodiert, allen Gegnern innerhalb von 10 Metern (57.75% der Zaubermacht) Schattenschaden zufügt und sie mit 'Verderbnis' belegt.\n\nDie Saat detoniert früher, wenn das Ziel von anderen Explosionen getroffen wird oder durch Eure Zauber (Schattenzaubermacht * 50 / 100) Schaden erleidet." }
